    text:'五更鼓罢，紫宸殿升座，百官山呼万岁。丞相<b>沈素</b>执笏出列，声音不高，却字字清楚：<br>「下官启奏：太后千秋在即，礼部拟加仪注十二抬、乐舞八佾，以彰陛下孝治。恳请陛下恩准。」<br>她顿了顿，补了一句：「只是……需支内帑八万两。如何用度，请陛下圣裁。」',
