    text:'北境急报：游骑犯边。<b>{name}</b>主动请缨，只带了三百骑。<br>他冲在最前面，中箭十七处，死时还保持着挽弓的姿势。他留下的遗书只有一句：「末将无脸见人，唯有一死报陛下。」<br>你把那封信看了三遍。他是去打仗，还是去寻死，你心里清楚。<br>萧破军在灵前站了一整天，一句话没说。临走时，她看了你一眼——那一眼，你记了很多年。',
