    text:'你醒来时，宫门已经换了人。<br><b>{name}</b>站在阶下，穿着他当年入翰林时的那身青袍——十年了，他一直留着。他笑着朝你一揖，姿态和十年前一模一样。<br>「陛下，」他说，「臣那本账，今日终于记完了。」<br>你没有问他是怎么办到的。你只是看着他，忽然想起很久以前那个笑起来很好看、也很好用的年轻人。<br>原来他一直在等这一天。',
